SELECT c_type,status,completed,deleted,COUNT(*) AS event_count
FROM w_lw_incident GROUP BY c_type,status,completed,deleted ORDER BY c_type,status;
SELECT event_type,COUNT(*) AS emergency_count
FROM w_lw_incident
WHERE c_type='4' AND status='1' AND completed=0 AND deleted=0
GROUP BY event_type ORDER BY event_type;
